contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    // take a dummy parameter to satisfy the template requirement; also allow sending Ether to this test for realism
    function run(uint dummy) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // observe before-values
        uint beforeBal = address(c).balance;
        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint balBeforeMe = address(this).balance;
        // perform the state-changing call as owner (this contract is the owner)
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        // observe after-values
        uint afterBal = address(c).balance;
        uint afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint balAfterMe = address(this).balance;
        // Assert the general invariant: either revert leaves state/balances unchanged, or success zeros C's balance and transfers that amount to caller; depositsCount must not change in either case.
        assert(
            reverted ? (afterBal == beforeBal && afterCount == beforeCount && balAfterMe == balBeforeMe)
                     : (afterBal == 0 && afterCount == beforeCount && balAfterMe == balBeforeMe + beforeBal)
        );
    }
    receive() external payable {}
}

