pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 dummy) internal {
        vm.deal(address(c), VALUE_CAP);
        uint beforeBal = address(c).balance;
        uint256 beforeCount;
        try c.depositsCount() returns (uint256 __r) { beforeCount = __r; } catch { return; }
        uint balBeforeMe = address(this).balance;
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterBal = address(c).balance;
        uint256 afterCount;
        try c.depositsCount() returns (uint256 __r) { afterCount = __r; } catch { return; }
        uint balAfterMe = address(this).balance;
        assertTrue(reverted ? (afterBal == beforeBal && afterCount == beforeCount && balAfterMe == balBeforeMe)
                     : (afterBal == 0 && afterCount == beforeCount && balAfterMe == balBeforeMe + beforeBal));
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable {}
}
